  var zp = null, zpLayers = [], zpText, band = null;
  /* Wörter in Masken packen (Überschriften steigen hoch) */
  document.querySelectorAll('.rise').forEach(function (el) {
    var delay = 0, step = 0.055;
    function wrapText(node, soft) {
      var frag = document.createDocumentFragment();
      var parts = node.nodeValue.split(/(\s+)/);
      parts.forEach(function (t) {
        if (!t) return;
        if (/^\s+$/.test(t)) { frag.appendChild(document.createTextNode(' ')); return; }
        var w = document.createElement('span'); w.className = 'w';
        var wi = document.createElement('span'); wi.className = 'wi' + (soft ? ' soft' : ''); wi.textContent = t;
        wi.style.transitionDelay = delay.toFixed(3) + 's'; delay += step;
        w.appendChild(wi); frag.appendChild(w);
      });
      return frag;
    }
    function walk(parent, soft) {
      Array.prototype.slice.call(parent.childNodes).forEach(function (n) {
        if (n.nodeType === 3) { parent.replaceChild(wrapText(n, soft), n); }
        else if (n.nodeType === 1) {
          var isSoft = soft || n.classList.contains('soft');
          if (n.tagName === 'EM' || n.tagName === 'SPAN') { n.classList.remove('soft'); walk(n, isSoft); }
        }
      });
    }
    walk(el, false);
  });

  /* Film-Sätze: Buchstaben rollen, {…} im Verlauf */
  document.querySelectorAll('[data-roll]').forEach(function (el) {
    var txt = el.getAttribute('data-roll'), t = 0.15 + parseFloat(el.dataset.delay || 0), step = 0.02;
    var m = /^(.*?)\s*\{([^}]+)\}(.*)$/.exec(txt);
    var chunks = m ? [[m[1], false], [m[2], true], [m[3], false]] : [[txt, false]];
    chunks.forEach(function (c, ci) {
      if (!c[0]) return;
      if (ci === 1) t += parseFloat(el.dataset.gap || 0.28);
      var total = Array.from(c[0].replace(/\s+/g, '')).length, li = 0;
      c[0].trim().split(/\s+/).forEach(function (word, wi, arr) {
        if (el.childNodes.length > 1) el.appendChild(document.createTextNode(' '));
        var rw = document.createElement('span'); rw.className = 'rw'; rw.setAttribute('aria-hidden', 'true');
        Array.from(word).forEach(function (ch) {
          var rm = document.createElement('span'); rm.className = 'rm';
          var rc = document.createElement('span'); rc.className = 'rc' + (c[1] ? ' rb' : ''); rc.textContent = ch;
          if (c[1]) { rc.style.setProperty('--a', (li / total).toFixed(3)); rc.style.setProperty('--b', ((li + 1) / total).toFixed(3)); li++; }
          t += step; rc.style.transitionDelay = t.toFixed(3) + 's';
          rm.appendChild(rc); rw.appendChild(rm);
        });
        el.appendChild(rw); t += step;
      });
    });
  });


  /* Hero: markiertes Wort flackert Buchstabe für Buchstabe im Verlauf an (wie „offline" auf der Website) */
  document.querySelectorAll('[data-flicker]').forEach(function (el) {
    var word = el.textContent, letters = Array.from(word), n = letters.length; el.textContent = '';
    letters.forEach(function (ch, i) {
      var s = document.createElement('span'); s.className = 'fl'; s.textContent = ch;
      s.style.setProperty('--a', (i / n).toFixed(3)); s.style.setProperty('--b', ((i + 1) / n).toFixed(3));
      s.style.animationDelay = (parseFloat(el.dataset.fd || 1.05) + i * 0.09).toFixed(2) + 's'; el.appendChild(s);
    });
  });
  /* Laufband läuft nur im Bild */
  document.querySelectorAll('.mq').forEach(function (mq) { var track = mq.querySelector('.mq-track'); new IntersectionObserver(function (e) { track.dataset.paused = e[0].isIntersecting ? 'false' : 'true'; }, { threshold: 0 }).observe(mq); });

  /* Bühnen 05/06: Fortschritt aus dem Scrollweg, Schritt-Klasse schaltet, die Übergänge macht CSS */
  var stages = Array.prototype.map.call(document.querySelectorAll('[data-stage]'), function (el) {
    return { el: el, n: parseInt(el.dataset.steps, 10), steps: el.querySelectorAll('.step'), dots: el.querySelectorAll('.step-dots i'), lives: el.querySelectorAll('.life'), hots: el.querySelectorAll('.hot'), cur: -1 };
  });
  function stageTick() {
    stages.forEach(function (st) {
      var r = st.el.getBoundingClientRect(), total = r.height - innerHeight; if (total <= 0) return;
      if (r.top < innerHeight * 0.8 && r.bottom > 0) st.el.classList.add('on');
      var p = Math.min(1, Math.max(0, -r.top / total)), i = Math.min(st.n - 1, Math.floor(p * st.n * 0.985));
      if (r.top > innerHeight * 0.6) i = 0;
      if (i === st.cur) return;
      var prev = st.cur; st.cur = i; st.el.dataset.step = i;
      st.steps.forEach(function (e, k) { e.classList.toggle('is', k === i); e.classList.toggle('was', k < i); });
      st.dots.forEach(function (d, k) { d.classList.toggle('on', k <= i); });
      st.lives.forEach(function (l, k) { l.classList.toggle('is', k === i); l.classList.toggle('was', k < i); });
      st.hots.forEach(function (h) { h.classList.toggle('live', parseInt(h.dataset.on, 10) === i); });
    });
  }
  if (stages.length) { addEventListener('scroll', function () { requestAnimationFrame(stageTick); }, { passive: true }); addEventListener('resize', stageTick); stageTick(); setTimeout(stageTick, 400); }

  /* Sichtbar werden */
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) {
      if (!en.isIntersecting) return;
      en.target.classList.add('on'); io.unobserve(en.target);
    });
  }, { rootMargin: '0px 0px -4% 0px' });
  document.querySelectorAll('.rv, .fl, .rise, .station, .pola, .ph, [data-scatter], .lv').forEach(function (e) { if (!e.closest('[data-gs]')) io.observe(e); });
  /* Fakten: Funkenweg messen, Jahr hochzählen, sobald der Block im Bild ist */
  var facts = document.querySelector('[data-facts]');
  if (facts) {
    new IntersectionObserver(function (en, o) {
      if (!en[0].isIntersecting) return; o.disconnect();
      facts.style.setProperty('--w', facts.clientWidth + 'px');
      var cnt = facts.querySelector('[data-count]');
      if (cnt && !reduce) { var end = parseInt(cnt.dataset.count, 10), start = end - 12, t0 = null;
        var step = function (ts) { if (!t0) t0 = ts; var k = Math.min(1, (ts - t0 - 500) / 1300); if (k < 0) { requestAnimationFrame(step); return; } var e = 1 - Math.pow(1 - k, 3); cnt.textContent = Math.round(start + (end - start) * e); if (k < 1) requestAnimationFrame(step); };
        requestAnimationFrame(step); }
    }, { rootMargin: '0px 0px -10% 0px' }).observe(facts);
  }
  /* Video: wenn der Browser das Abspielen verweigert (Stromsparmodus), startet die erste Berührung alle sichtbaren Filme */
  function kick() { document.querySelectorAll('.film.near video').forEach(function (v) { var p = v.play(); if (p && p.catch) p.catch(function () {}); }); }
  ['touchstart', 'pointerdown', 'keydown'].forEach(function (ev) { addEventListener(ev, kick, { passive: true, once: true }); });

  /* Film-Fenster: Satz startet, Video lädt und läuft nur in der Nähe */
  var films = document.querySelectorAll('[data-film]');
  var fio = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) {
      var f = en.target, v = f.querySelector('video');
      if (en.isIntersecting) {
        if (en.intersectionRatio > 0.35) f.classList.add('on');
        if (v && !v.dataset.ready) {
          v.dataset.ready = '1'; v.poster = v.dataset.poster;
          v.querySelectorAll('source').forEach(function (s) { s.src = s.dataset.src; }); v.load();
        }
        if (v) { var p = v.play(); if (p && p.catch) p.catch(function () {}); }
      } else if (v) { v.pause(); }
    });
  }, { rootMargin: '12% 0px 12% 0px', threshold: [0, 0.35] });
  films.forEach(function (f) { fio.observe(f); });
  var nio = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) { en.target.classList.toggle('near', en.isIntersecting); });
  }, { rootMargin: '45% 0px 45% 0px' });
  films.forEach(function (f) { nio.observe(f); });

  /* Parallax: wenige Elemente, nur transform, nur im Bild */
  var pars = Array.prototype.map.call(document.querySelectorAll('[data-par]'), function (el) { return { el: el, k: parseFloat(el.dataset.par), top: 0, h: 0 }; });
  function measure() {
    vh = innerHeight;
    pars.forEach(function (p) { var r = p.el.getBoundingClientRect(); p.top = r.top + scrollY; p.h = r.height; });
    if (zp) { var rz = zp.getBoundingClientRect(); zp._top = rz.top + scrollY; zp._h = rz.height; }
    tick();
  }
  var ticking = false;
  function tick() {
    ticking = false;
    var y = scrollY;
    if (!reduce) pars.forEach(function (p) {
      if (p.top + p.h < y - vh || p.top > y + vh * 2) return;
      var c = p.top + p.h / 2 - (y + vh / 2);
      p.el.style.transform = 'translate3d(0,' + (-c * p.k).toFixed(1) + 'px,0)';
    });
    if (zp) {
      var pz = (y - zp._top) / (zp._h - vh);
      if (pz >= -0.05 && pz <= 1.05) {
        var q = Math.min(1, Math.max(0, pz));
        zpLayers.forEach(function (l) { l.el.style.transform = 'scale(' + (1 + (l.s - 1) * q).toFixed(4) + ')'; });
        zp.classList.toggle('fin', q > 0.78); zp.classList.toggle('on', q > 0.05);
        if (q > 0.78) { if (!zp._t) zp._t = setTimeout(function () { zp.classList.add('fin2'); }, 1100); } else if (zp._t) { clearTimeout(zp._t); zp._t = 0; zp.classList.remove('fin2'); }
      }
    }
  }
  function onScroll() { if (!ticking) { ticking = true; requestAnimationFrame(tick); } }
  addEventListener('scroll', onScroll, { passive: true });
  addEventListener('resize', measure);
  addEventListener('load', measure);
  measure();

  /* Pfad: Linie füllt bis zur letzten sichtbaren Station */
  var path = document.querySelector('[data-path]');
  if (path) {
    var rail = path.querySelector('.rail i'), stations = path.querySelectorAll('[data-station]');
    var sio = new IntersectionObserver(function () {
      var last = -1; stations.forEach(function (s, i) { if (s.classList.contains('on')) last = i; });
      if (last < 0) return;
      var r = path.getBoundingClientRect(), sr = stations[last].getBoundingClientRect();
      rail.style.transform = 'scaleY(' + Math.min(1, (sr.top - r.top + 12) / r.height).toFixed(3) + ')';
      rail.style.transition = 'transform .9s cubic-bezier(0.22, 1, 0.36, 1)';
    }, { rootMargin: '0px 0px -4% 0px' });
    stations.forEach(function (s) { sio.observe(s); });
  }

  /* Rahmen neigen sich zur Maus (nur Zeiger-Geräte) */
  if (matchMedia('(hover: hover) and (pointer: fine)').matches) {
    document.querySelectorAll('[data-tilt]').forEach(function (el) {
      el.addEventListener('mousemove', function (e) {
        var r = el.getBoundingClientRect();
        var x = (e.clientX - r.left) / r.width - 0.5, y = (e.clientY - r.top) / r.height - 0.5;
        el.style.setProperty('--ry', (x * 10).toFixed(2) + 'deg'); el.style.setProperty('--rx', (-y * 8).toFixed(2) + 'deg');
      });
      el.addEventListener('mouseleave', function () { el.style.setProperty('--ry', '0deg'); el.style.setProperty('--rx', '0deg'); });
    });
  }

  /* ========== Einladung: seitenweite Kleinigkeiten (Fassung 4, 01.11.2026). Die Abschnitte bringen ihre Skripte selbst mit. ========== */

  /* ===== Schweben überall (01.11.2026): grössere Fotos in einem Rahmen bekommen data-sw, sobald ihre Gruppe den unteren Rand (+4 %) erreicht
     und die Bilder geladen sind, startet der Auftritt. Ausgenommen: Kopf, Hero, Laufbänder, Fenster, Handys, App-Fenster, Bildschirmbilder, Logos, Rollbänder in 04. ===== */
  (function () {
    var aus = '.top, #top, .hero-logo, .mq, .band, .film, .phone, .win, .j6-reel, [data-sw-aus]';
    var screen = /(app_|story-|feed-|frame-|calendar|newsfeed|messenger|profile|map-|live-pulse|channel|community|logo|pol-|phone-frame|qr-)/;
    var frames = [];
    document.querySelectorAll('main img').forEach(function (img) {
      if (img.closest(aus) || screen.test(img.getAttribute('src') || '')) return;
      var zt = img, fr = img.parentElement; if (!fr) return;
      var clipped = function (el) { var s = getComputedStyle(el); return /hidden|clip/.test(s.overflow + s.overflowX); };
      /* Bilderstapel (z. B. Branchen): das Bild liegt in einer Hülle, die den Rahmen füllt; dann zoomt die Hülle */
      if (!clipped(fr) && fr.parentElement && clipped(fr.parentElement) && fr.tagName === 'DIV') { zt = fr; fr = fr.parentElement; }
      if (fr.hasAttribute('data-sw') || !clipped(fr)) return;
      if (getComputedStyle(img).objectFit === 'contain') return;
      var r = fr.getBoundingClientRect(); if (r.width < 160 || r.height < 110) return;
      fr.setAttribute('data-sw', ''); zt.classList.add('sw-img'); frames.push(fr);
    });
    /* Reihenfolge innerhalb einer Gruppe: von links nach rechts, höchstens fünf Stufen */
    var groups = new Map();
    frames.forEach(function (fr) { var g = fr.parentElement; if (!groups.has(g)) groups.set(g, []); groups.get(g).push(fr); });
    groups.forEach(function (list) { list.sort(function (a, b) { return a.getBoundingClientRect().left - b.getBoundingClientRect().left; }); list.forEach(function (fr, i) { fr.style.setProperty('--swi', Math.min(i, 4)); }); });
    function bereit(fr, fn) {
      var img = fr.querySelector('img');
      if (!img || (img.complete && img.naturalWidth)) return fn();
      img.loading = 'eager';
      var done = false; function go() { if (!done) { done = true; fn(); } }
      img.addEventListener('load', go, { once: true }); img.addEventListener('error', go, { once: true }); setTimeout(go, 1500);
    }
    if (!window.IntersectionObserver || reduce) { frames.forEach(function (fr) { fr.classList.add('da'); }); return; }
    var sio = new IntersectionObserver(function (es) {
      es.forEach(function (en) { if (!en.isIntersecting) return; sio.unobserve(en.target); bereit(en.target, function () { en.target.classList.add('da'); }); });
    }, { rootMargin: '0px 0px 4% 0px' });
    frames.forEach(function (fr) { sio.observe(fr); });
  })();

  /* ===== Früh laden (01.11.2026: «Bilder laden sehr langsam und sehr spät»): Bilder holen, wenn sie zweieinhalb Bildschirmhöhen entfernt sind ===== */
  (function () {
    var lazy = document.querySelectorAll('img[loading="lazy"]');
    if (!window.IntersectionObserver) { Array.prototype.forEach.call(lazy, function (i) { i.loading = 'eager'; }); return; }
    var pio = new IntersectionObserver(function (es) {
      es.forEach(function (en) { if (en.isIntersecting) { en.target.loading = 'eager'; pio.unobserve(en.target); } });
    }, { rootMargin: '250% 0px 250% 0px' });
    Array.prototype.forEach.call(lazy, function (i) { pio.observe(i); });
  })();

  /* ===== Fenster früh laden (wie „für Orte“): der Film lädt zwei Bildschirmhöhen vorher, damit das Fenster nie schwarz ist ===== */
  (function () {
    if (!window.IntersectionObserver) return;
    var lio = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (!en.isIntersecting) return; var v = en.target.querySelector('video'); lio.unobserve(en.target);
        if (v && !v.dataset.ready) { v.dataset.ready = '1'; v.poster = v.dataset.poster; v.querySelectorAll('source').forEach(function (s) { s.src = s.dataset.src; }); v.load(); }
      });
    }, { rootMargin: '200% 0px 200% 0px' });
    document.querySelectorAll('[data-film]').forEach(function (f) { lio.observe(f); });
  })();

