(function (root) {
  if (!root) return;
  root.querySelectorAll('[data-o]').forEach(function (e) { io.observe(e); });
  var chain = root.querySelector('.c-chain'), rail = root.querySelector('.c-rail i'), steps = root.querySelectorAll('.c-step');
  function place() {
    var box = rail.parentNode, a = steps[0].offsetTop + 16, b = steps[steps.length - 1].offsetTop + 16;
    box.style.top = a + 'px'; box.style.bottom = 'auto'; box.style.height = (b - a) + 'px';
  }
  place(); addEventListener('resize', function () { place(); fill(); }); addEventListener('load', function () { place(); fill(); });
  function fill() {
    var last = -1; steps.forEach(function (s, i) { if (s.classList.contains('on')) last = i; });
    if (last < 0) return;
    var box = rail.parentNode;
    rail.style.transform = 'scaleY(' + Math.min(1, Math.max(0, (steps[last].offsetTop + 16 - box.offsetTop) / box.offsetHeight)).toFixed(3) + ')';
  }
  var sio = new IntersectionObserver(function (en) {
    en.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('on'); sio.unobserve(e.target); } });
    fill();
  }, { rootMargin: '0px 0px -12% 0px' });
  steps.forEach(function (s) { sio.observe(s); });
})(document.querySelector('.am-cr'));

} catch (e) { console.error('Abschnitt creators', e); }
