/* Abschnitt freedom */
try {

(function (root) {
  if (!root) return;
  var axis = root.querySelector('.f-axis'), spine = root.querySelector('.f-spine');
  root.querySelectorAll('.f-ln').forEach(function (e) { io.observe(e); });
  if (reduce) return;
  /* Die Verlaufsachse wächst mit dem Lesen nach unten, die Zeilen setzen ihre Äste an */
  function tick() {
    var r = axis.getBoundingClientRect(); if (!r.height) return;
    var p = Math.min(1, Math.max(0, (innerHeight * 0.78 - r.top) / r.height));
    spine.style.setProperty('--p', p.toFixed(4));
  }
  addEventListener('scroll', function () { requestAnimationFrame(tick); }, { passive: true });
  addEventListener('resize', tick); root.addEventListener('wahl:zeigen', function () { setTimeout(tick, 50); }); tick();
})(document.querySelector('.am-free'));

} catch (e) { console.error('Abschnitt freedom', e); }
/* Abschnitt early */
try {

(function (root) {
  if (!root) return;
  var wrap = root.querySelector('.st-wrap'), ss = root.querySelectorAll('.st-s');
  new IntersectionObserver(function (en, o) { if (en[0].isIntersecting) { wrap.classList.add('on'); o.disconnect(); } }, { threshold: 0.45 }).observe(wrap);
  /* Handy: die Kanten liegen genau über der jeweiligen Stufe */
  function place() { if (!wrap.offsetParent) return; wrap.style.setProperty('--y2', ss[1].offsetTop + 'px'); wrap.style.setProperty('--y3', ss[2].offsetTop + 'px'); }
  addEventListener('resize', place); addEventListener('load', place); root.addEventListener('wahl:zeigen', function () { setTimeout(place, 30); }); place();
})(document.querySelector('.am-early'));

} catch (e) { console.error('Abschnitt early', e); }
/* Abschnitt next */
try {

(function (root) {
  if (!root) return;
  root.querySelectorAll('.n1-step').forEach(function (e) { io.observe(e); });
  /* Die Scanlinie fährt über den Code, während man die Schritte liest */
  var qr = root.querySelector('.n1-qr'), scan = root.querySelector('.n1-scan'), right = root.querySelector('.n1-right'), wide = matchMedia('(min-width: 1000px)');
  function tick() {
    var q = qr.getBoundingClientRect(); if (!q.height) return;
    var vh = innerHeight, p;
    if (wide.matches) { var r = right.getBoundingClientRect(); p = (vh * .78 - r.top) / (r.height * .92); }
    else { p = (vh * .9 - q.top) / (q.height + vh * .3); }
    p = Math.max(0, Math.min(1, p));
    if (reduce) p = 1;
    scan.style.setProperty('--y', (p * (q.height + 88)).toFixed(1) + 'px');
  }
  addEventListener('scroll', function () { requestAnimationFrame(tick); }, { passive: true });
  addEventListener('resize', tick);
  root.addEventListener('wahl:zeigen', function () { requestAnimationFrame(tick); });
  tick();
})(document.querySelector('.am-next'));

} catch (e) { console.error('Abschnitt next', e); }

